static std::vector<fs::path> Pick(bool folders,bool multi,bool archives){std::vector<fs::path> out;IFileOpenDialog* dialog=nullptr;if(FAILED(CoCreateInstance(CLSID_FileOpenDialog,nullptr,CLSCTX_INPROC_SERVER,IID_PPV_ARGS(&dialog))))return out;DWORD options=0;dialog->GetOptions(&options);dialog->SetOptions(options|FOS_FORCEFILESYSTEM|FOS_PATHMUSTEXIST|(folders?FOS_PICKFOLDERS:0)|(multi?FOS_ALLOWMULTISELECT:0));dialog->SetTitle(folders?L"选择文件夹":archives?L"选择压缩包（可多选）":L"选择要压缩的文件（可多选）");if(archives){COMDLG_FILTERSPEC filters[]={{L"常见压缩包",L"*.zip;*.7z;*.rar;*.tar;*.gz;*.tgz;*.bz2;*.xz;*.zst;*.cab;*.iso;*.001;*.wim;*.apk;*.jar"},{L"所有文件",L"*.*"}};dialog->SetFileTypes(2,filters);}if(SUCCEEDED(dialog->Show(g.window))){IShellItemArray* items=nullptr;if(SUCCEEDED(dialog->GetResults(&items))){DWORD count=0;items->GetCount(&count);for(DWORD i=0;i<count;i++){IShellItem* item=nullptr;if(SUCCEEDED(items->GetItemAt(i,&item))){PWSTR p=nullptr;if(SUCCEEDED(item->GetDisplayName(SIGDN_FILESYSPATH,&p))){out.emplace_back(p);CoTaskMemFree(p);}item->Release();}}items->Release();}}dialog->Release();return out;}
static void Add(const std::vector<fs::path>& paths,bool fromDrop=false){if(g.busy)return;if(paths.empty())return;if(fromDrop){bool all=std::all_of(paths.begin(),paths.end(),[](auto& p){return fs::is_regular_file(p)&&IsArchive(p);});if(g.sources.empty())g.pack=!all;}for(const auto& input:paths){if(!fs::exists(input))continue;auto p=g.pack?fs::absolute(input):FirstVolume(input);if(!g.pack&&!fs::is_regular_file(p)){g.status=L"解压模式请添加压缩包；文件夹可在压缩模式中添加。";continue;}if(std::find(g.sources.begin(),g.sources.end(),p)==g.sources.end()&&g.sources.size()<10000)g.sources.push_back(p);}g.catalogMode=false;g.folderPrefix.clear();g.catalog={};g.password.clear();g.lastOutput.clear();g.status=L"已添加 "+std::to_wstring(g.sources.size())+L" 个项目";g.detail=g.pack?L"选择文件，点「开始压缩」即可。":L"重名自动避让，每个压缩包解压到独立文件夹。";UpdateList();Layout();InvalidateRect(g.window,nullptr,FALSE);}
static void Switch(bool pack){if(g.busy)return;if(g.pack!=pack){g.sources.clear();g.catalog={};g.password.clear();g.catalogMode=false;}g.pack=pack;g.status=L"准备好了";g.lastOutput.clear();g.detail=L"文件只在你的电脑上处理";UpdateList();Layout();InvalidateRect(g.window,nullptr,FALSE);}
