 case WM_SIZE:Layout();InvalidateRect(h,nullptr,FALSE);return 0;
 case WM_DPICHANGED:{g.dpi=HIWORD(wp);g.fonts.Create(g.dpi);for(auto c:g.controls)SendMessageW(c,WM_SETFONT,(WPARAM)g.fonts.body,TRUE);SendMessageW(g.list,WM_SETFONT,(WPARAM)g.fonts.body,TRUE);SendMessageW(g.search,WM_SETFONT,(WPARAM)g.fonts.body,TRUE);auto rc=(RECT*)lp;SetWindowPos(h,nullptr,rc->left,rc->top,rc->right-rc->left,rc->bottom-rc->top,SWP_NOZORDER|SWP_NOACTIVATE);Layout();return 0;}
