 case WM_DRAWITEM:{auto item=(DRAWITEMSTRUCT*)lp;if(item->CtlType!=ODT_BUTTON)break;int id=item->CtlID;bool sidebar=id==ID_EXTRACT||id==ID_PACK||id==ID_HELP||id==ID_ASSOC;bool selected=(id==ID_EXTRACT&&!g.pack)||(id==ID_PACK&&g.pack);bool primary=id==ID_GO;bool disabled=(item->itemState&ODS_DISABLED)!=0;bool pressed=(item->itemState&ODS_SELECTED)!=0;Fill(item->hDC,item->rcItem,sidebar?nav:bg);COLORREF fill=sidebar?(selected?RGB(41,73,72):nav):primary?(disabled?RGB(174,202,194):pressed?RGB(9,100,89):accent):RGB(255,255,255);COLORREF color=sidebar?(selected?RGB(156,235,213):RGB(171,192,192)):primary?RGB(255,255,255):disabled?muted:ink;Round(item->hDC,item->rcItem,fill,g.S(12),sidebar||primary?CLR_INVALID:lineColor);Label(item->hDC,Text(item->hwndItem),item->rcItem,primary?g.fonts.bold:g.fonts.body,color,DT_CENTER|DT_VCENTER|DT_SINGLELINE);if(item->itemState&ODS_FOCUS){RECT r=item->rcItem;InflateRect(&r,-4,-4);DrawFocusRect(item->hDC,&r);}return TRUE;}
 case WM_CTLCOLORSTATIC:case WM_CTLCOLOREDIT:SetTextColor((HDC)wp,ink);SetBkColor((HDC)wp,RGB(255,255,255));return (LRESULT)GetStockObject(WHITE_BRUSH);
 case WM_COMMAND:if(LOWORD(wp)==ID_SEARCH&&HIWORD(wp)==EN_CHANGE){UpdateList();return 0;}Command(LOWORD(wp));return 0;
 case WM_NOTIFY:{auto nm=(NMHDR*)lp;if(nm->hwndFrom==g.list&&nm->code==LVN_ITEMCHANGED){UpdatePrimary();return 0;}if(nm->hwndFrom==g.list&&nm->code==LVN_COLUMNCLICK&&g.catalogMode){auto click=(NMLISTVIEW*)lp;if(g.sortColumn==click->iSubItem)g.sortDescending=!g.sortDescending;else{g.sortColumn=click->iSubItem;g.sortDescending=false;}UpdateList();return 0;}if(nm->hwndFrom==g.list&&nm->code==NM_DBLCLK&&g.catalogMode){auto item=(NMITEMACTIVATE*)lp;if(item->iItem>=0&&(size_t)item->iItem<g.visible.size()){auto& entry=g.catalog.entries[g.visible[item->iItem]];if(entry.directory){g.folderPrefix=entry.name;std::replace(g.folderPrefix.begin(),g.folderPrefix.end(),L'/',L'\\');if(g.folderPrefix.back()!=L'\\')g.folderPrefix+=L'\\';SetWindowTextW(g.search,L"");UpdateList();g.status=L"文件夹："+entry.name;InvalidateRect(h,nullptr,FALSE);}else Command(ID_PREVIEW);}return 0;}if(nm->hwndFrom==g.list&&nm->code==LVN_GETDISPINFOW){auto info=(NMLVDISPINFOW*)lp;static thread_local std::wstring value;if(info->item.iItem<0||(size_t)info->item.iItem>=g.visible.size())return 0;size_t i=g.visible[info->item.iItem];int col=info->item.iSubItem;bool folder=false;if(g.catalogMode){auto& e=g.catalog.entries[i];folder=e.directory;value=col==0?e.name:col==1?(folder?L"—":Size(e.size)):folder?L"文件夹":fs::path(e.name).extension().wstring();}else{auto& p=g.sources[i];std::error_code ec;folder=fs::is_directory(p,ec);if(col==0)value=p.filename().wstring();else if(col==1){auto n=folder?0:fs::file_size(p,ec);value=folder?L"文件夹":ec?L"无法读取":Size(n);}else value=folder?L"文件夹":p.extension().wstring();}if(info->item.mask&LVIF_TEXT)info->item.pszText=value.data();return 0;}if(nm->hwndFrom==g.list&&nm->code==LVN_KEYDOWN){auto key=(NMLVKEYDOWN*)lp;if(key->wVKey==VK_DELETE)Command(g.catalogMode?ID_DELETE_ARCHIVE:ID_REMOVE);if(key->wVKey==VK_RETURN&&g.catalogMode)Command(ID_PREVIEW);return 0;}break;}
 case WM_DROPFILES:{HDROP drop=(HDROP)wp;std::vector<fs::path> paths;UINT count=std::min(10000U,DragQueryFileW(drop,0xFFFFFFFF,nullptr,0));for(UINT i=0;i<count;i++){UINT n=DragQueryFileW(drop,i,nullptr,0);std::wstring p(n+1,0);DragQueryFileW(drop,i,p.data(),n+1);p.resize(n);paths.emplace_back(p);}DragFinish(drop);try{Add(paths,true);}catch(...){MessageBoxW(h,L"无法读取拖入的文件。",L"小马压缩",MB_OK);}return 0;}
 case WM_PROGRESS:{std::unique_ptr<Progress> p((Progress*)lp);g.percent=p->percent;g.detail=p->detail;auto card=R(224,129,g.w-256,135);auto footer=R(224,g.h-80,g.w-256,70);InvalidateRect(h,&card,FALSE);InvalidateRect(h,&footer,FALSE);return 0;}
 case WM_DONE:{std::unique_ptr<Result> r((Result*)lp);if(g.worker.joinable())g.worker.join();g.busy=false;g.percent=-1;EnableWindow(g.Get(ID_CANCEL),TRUE);g.status=r->message;if(!r->outputs.empty())g.lastOutput=r->outputs.back();if(r->ok&&r->listing){g.catalog=std::move(r->catalog);g.catalogMode=true;g.folderPrefix.clear();SetWindowTextW(g.search,L"");UpdateList();}g.detail=!g.lastOutput.empty()?g.lastOutput.wstring():r->cancelled?L"原始文件未修改。":r->ok?L"文件只在你的电脑上处理":L"未覆盖原文件，可检查后重试。";Layout();InvalidateRect(h,nullptr,FALSE);if(g.quitWhenDone){DestroyWindow(h);return 0;}if(r->ok&&r->showPreview)ShowText(std::move(r->preview));if(r->ok&&r->information&&!g.diagnostics)MessageBoxW(h,r->message.c_str(),L"压缩包信息",MB_OK|MB_ICONINFORMATION);if(r->ok&&r->refresh){Start(1);return 0;}if(r->password&&!g.diagnostics){if(g.pending==2&&!r->outputs.empty()){g.sources.erase(g.sources.begin(),g.sources.begin()+r->outputs.size());g.catalogMode=false;g.catalog={};UpdateList();Layout();}Dialog d;if(Ask(d)){g.password=d.password;Start(g.pending);}}else if(!r->ok&&!r->cancelled&&!g.diagnostics)MessageBoxW(h,r->message.c_str(),L"任务没有完成",MB_OK|MB_ICONINFORMATION);return 0;}
