 if(args.size()>=2&&args[0]==L"--self-test"){int result=SelfTest(AppDirectory()/L"engine"/L"7z.exe",args[1]);if(SUCCEEDED(com))CoUninitialize();return result;}
 WNDCLASSEXW cls{sizeof(cls)};cls.hInstance=instance;cls.lpfnWndProc=MainProc;cls.lpszClassName=L"XiaomaArchive";cls.hCursor=LoadCursorW(nullptr,IDC_ARROW);cls.hIcon=LoadIconW(instance,MAKEINTRESOURCEW(1));cls.hIconSm=cls.hIcon;RegisterClassExW(&cls);WNDCLASSW dialog{};dialog.hInstance=instance;dialog.lpfnWndProc=DialogProc;dialog.lpszClassName=L"XiaomaOptions";dialog.hCursor=LoadCursorW(nullptr,IDC_ARROW);dialog.hbrBackground=(HBRUSH)GetStockObject(WHITE_BRUSH);RegisterClassW(&dialog);
 UINT dpi=GetDpiForSystem();g.dpi=dpi;RECT rc{0,0,MulDiv(1040,dpi,96),MulDiv(700,dpi,96)};AdjustWindowRectExForDpi(&rc,WS_OVERLAPPEDWINDOW,FALSE,0,dpi);HWND h=CreateWindowExW(0,cls.lpszClassName,L"小马压缩",WS_OVERLAPPEDWINDOW|WS_CLIPCHILDREN,CW_USEDEFAULT,CW_USEDEFAULT,rc.right-rc.left,rc.bottom-rc.top,nullptr,nullptr,instance,nullptr);if(!h){if(SUCCEEDED(com))CoUninitialize();return 1;}RECT scaled{0,0,g.S(1040),g.S(700)};AdjustWindowRectExForDpi(&scaled,WS_OVERLAPPEDWINDOW,FALSE,0,g.dpi);SetWindowPos(h,nullptr,0,0,scaled.right-scaled.left,scaled.bottom-scaled.top,SWP_NOMOVE|SWP_NOZORDER|SWP_NOACTIVATE);BOOL dark=TRUE;DwmSetWindowAttribute(h,20,&dark,sizeof(dark));DWM_WINDOW_CORNER_PREFERENCE corners=DWMWCP_ROUND;DwmSetWindowAttribute(h,DWMWA_WINDOW_CORNER_PREFERENCE,&corners,sizeof(corners));COLORREF titleColor=nav;DwmSetWindowAttribute(h,DWMWA_CAPTION_COLOR,&titleColor,sizeof(titleColor));
